module preprocess
#(
    parameter DIVIDEND_WIDTH = 8,
    parameter DIVISOR_WIDTH = 8,
    parameter FRACTION_WIDTH = 8
)
(
    input i_clk
    ,input i_rst_n
    ,input i_clken
    ,input [DIVIDEND_WIDTH-1'b1:1'b0] i_x
    ,input [DIVISOR_WIDTH-1'b1:1'b0] i_d
    ,output [3'd5:1'b0]o_m
    ,output [3'd5:1'b0]o_n
    ,output [DIVISOR_WIDTH+2'd2:1'b0] o_d_shift
    ,output [DIVIDEND_WIDTH+3'd4:1'b0] o_x_shift
);

    reg [DIVISOR_WIDTH+2'd2:1'b0] d_shift_r;
    reg [DIVIDEND_WIDTH+3'd4:1'b0] x_shift_r;
    reg valid_r;

    wire [(7'd66-DIVIDEND_WIDTH-7'd1):1'b0] find_one_x;
    wire [(7'd66-DIVISOR_WIDTH-7'd1):1'b0] find_one_d;

    assign o_d_shift = d_shift_r;
    assign o_x_shift = x_shift_r;
    
    assign  find_one_x=(DIVIDEND_WIDTH == 64)? 1'b0:{(7'd66-DIVIDEND_WIDTH-7'd0){1'b0}};
    assign  find_one_d=(DIVISOR_WIDTH == 64)? 1'b0:{(7'd66-DIVISOR_WIDTH-7'd0){1'b0}};

    wire [63:1'b0] find_one_x_1;
    wire [63:1'b0] find_one_d_1;
    assign find_one_x_1=(DIVIDEND_WIDTH == 64)? {i_x}:{find_one_x[(7'd66-DIVIDEND_WIDTH-7'd1):1'b1],i_x};
    assign find_one_d_1=(DIVISOR_WIDTH == 64)? {i_d}:{find_one_d[(7'd66-DIVISOR_WIDTH-7'd1):1'b1],i_d};
    //assign find_one_d_1=(DIVISOR_WIDTH == 64)? {i_d}:{find_one_d[(7'd66-DIVISOR_WIDTH-7'd2):1'b1],i_d};



    find_one find_one1(.i_din(find_one_x_1),.o_index(o_m));
    find_one find_one2(.i_din(find_one_d_1),.o_index(o_n));

generate
    case(DIVISOR_WIDTH)
    7'd4:begin
        always@(posedge i_clk or negedge i_rst_n)
        begin//d_shift_04
            if (!i_rst_n) d_shift_r<=0;
            else if (i_clken )begin
            case(o_n)
                6'd0:
                begin
                d_shift_r<={3'd0,i_d[0],{(DIVISOR_WIDTH-1'b1){1'b0}}};//d=0110 -> temp_d=000.110
                end
                6'd1:
                begin
                d_shift_r<={3'd0,i_d[1:1'b0],{(DIVISOR_WIDTH-2'd2){1'b0}}};
                end
                6'd2:
                begin
                d_shift_r<={3'd0,i_d[2:1'b0],{(DIVISOR_WIDTH-2'd3){1'b0}}};
                end
                6'd3:
                begin
                d_shift_r<={3'd0,i_d[3:1'b0]};
                end
            default:
            begin
                d_shift_r<={(DIVIDEND_WIDTH+3'd3){1'b0}};
            end
            endcase
            end
            else d_shift_r<=0;
        end
    end
